/**
 * The worker control plane. `Register` is authenticated with an operator API
 * key (`x-api-key`, Maintainer+); `WatchConfig`, `AckConfig`, `ReportHealth`,
 * `PollAgentUpdate` and `ShellChannel` are authenticated with the dynamic
 * refresh key (`x-refresh-key`) that `Register` returned.
 */
export type WorkerAgentDefinition = typeof WorkerAgentDefinition;
export const WorkerAgentDefinition = {
  name: "WorkerAgent",
  fullName: "guru.orchestration.agent.WorkerAgent",
  methods: {
    register: {
      name: "Register",
      requestType: RegisterRequest as typeof RegisterRequest,
      requestStream: false,
      responseType: RegisterReply as typeof RegisterReply,
      responseStream: false,
      options: {},
    },
    /**
     * Sends a keep-alive every `RegisterReply.stream_keepalive_secs` to a worker
     * that asked for them, so no proxy on the path sees a silent stream.
     */
    watchConfig: {
      name: "WatchConfig",
      requestType: WatchConfigRequest as typeof WatchConfigRequest,
      requestStream: false,
      responseType: ConfigRevision as typeof ConfigRevision,
      responseStream: true,
      options: {},
    },
    ackConfig: {
      name: "AckConfig",
      requestType: AckConfigRequest as typeof AckConfigRequest,
      requestStream: false,
      responseType: AckConfigReply as typeof AckConfigReply,
      responseStream: false,
      options: {},
    },
    /**
     * One report per interval for as long as the worker lives, one reply per
     * report the master recorded; the reply stream opens before the first report
     * is recorded. The stream closing does not mark the server offline — a proxy
     * cutting it is not the worker going away. Silence does: no report for
     * `health_offline_after`, and the master ends the stream with
     * `DEADLINE_EXCEEDED` and marks the server `Offline`.
     *
     * A worker built before the replies (tonic 0.14 `client_streaming`) takes
     * the first reply and drains the rest, so its call still ends only when the
     * stream does.
     */
    reportHealth: {
      name: "ReportHealth",
      requestType: HealthReport as typeof HealthReport,
      requestStream: true,
      responseType: ReportHealthReply as typeof ReportHealthReply,
      responseStream: true,
      options: {},
    },
    /**
     * Asked every `agent_update_poll_secs`: whether the operator requested an
     * update for this server, and how the previous attempt went.
     */
    pollAgentUpdate: {
      name: "PollAgentUpdate",
      requestType: PollAgentUpdateRequest as typeof PollAgentUpdateRequest,
      requestStream: false,
      responseType: PollAgentUpdateReply as typeof PollAgentUpdateReply,
      responseStream: false,
      options: {},
    },
    /**
     * Remote shell. Only a worker whose host opted in locally (and which
     * therefore advertised `remote_shell` at `Register`) opens it, right after
     * `Register`, authenticated with `x-refresh-key`. A newer registration
     * supersedes the stream, exactly as it does `WatchConfig`.
     *
     * The master is a stateless relay: it hands dashboard requests down and the
     * worker's replies and transcript events up, and stores nothing. Sessions,
     * their shells and their output buffers live on the worker and outlive the
     * stream. Both sides send a `ShellKeepAlive` every
     * `RegisterReply.stream_keepalive_secs` and end a stream that stays silent
     * for three of them.
     */
    shellChannel: {
      name: "ShellChannel",
      requestType: ShellUp as typeof ShellUp,
      requestStream: true,
      responseType: ShellDown as typeof ShellDown,
      responseStream: true,
      options: {},
    },
  },
} as const;

